"use client";

import * as React from "react";
import { motion, useReducedMotion } from "motion/react";
import { cn } from "@/lib/utils";

type Props = {
  value: number; // -1..+1
  size?: "sm" | "md";
  showLabels?: boolean;
  className?: string;
};

export function SentimentMeter({ value, size = "md", showLabels = true, className }: Props) {
  const reduced = useReducedMotion();
  const clamped = Math.max(-1, Math.min(1, value));
  // -1 -> -90deg, 0 -> 0deg, +1 -> +90deg
  const angle = clamped * 90;

  const px = size === "sm" ? 80 : 120;
  const h = size === "sm" ? 44 : 68;

  return (
    <div className={cn("inline-flex flex-col items-center gap-1", className)}>
      <svg
        width={px}
        height={h}
        viewBox="0 0 120 68"
        aria-hidden="true"
        className="overflow-visible"
      >
        {/* arc */}
        <defs>
          <linearGradient id="mt-sent-arc" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0%" stopColor="var(--color-bear)" />
            <stop offset="50%" stopColor="var(--color-muted-foreground)" />
            <stop offset="100%" stopColor="var(--color-bull)" />
          </linearGradient>
        </defs>
        <path
          d="M 8 60 A 52 52 0 0 1 112 60"
          fill="none"
          stroke="url(#mt-sent-arc)"
          strokeWidth="6"
          strokeLinecap="round"
        />
        {/* needle */}
        <motion.g
          style={{ originX: "60px", originY: "60px" } as React.CSSProperties}
          initial={reduced ? false : { rotate: 0 }}
          animate={{ rotate: angle }}
          transition={{ type: "spring", stiffness: 220, damping: 18 }}
        >
          <line
            x1="60"
            y1="60"
            x2="60"
            y2="14"
            stroke="var(--color-foreground)"
            strokeWidth="2"
            strokeLinecap="round"
          />
          <circle cx="60" cy="60" r="4" fill="var(--color-foreground)" />
        </motion.g>
      </svg>
      {showLabels && (
        <div className="flex w-full justify-between text-[10px] text-muted-foreground">
          <span>Bearish</span>
          <span>Neutral</span>
          <span>Bullish</span>
        </div>
      )}
    </div>
  );
}
